async function pollList(){
    if(!conversationList||listBusy||listStopped||document.hidden)return;
    listBusy=true;
    const ctrl=new AbortController();
    const timeout=setTimeout(()=>ctrl.abort(),8000);
    try{
        const res=await fetch(endpoint('listaViva',{conversacion_id:conversationId}),{credentials:'same-origin',cache:'no-store',signal:ctrl.signal,headers:{'X-Requested-With':'fetch'}});
        if(res.status===401||res.status===403){
            listStopped=true;conversationList.replaceChildren();return;
        }
        if(!res.ok)return;
        const data=await res.json();
        if(!data.ok||typeof data.html!=='string'||!Number.isInteger(data.total)||data.total<0||document.hidden)return;
        if(listSignature!==data.html){
            const focused=document.activeElement?.closest('[data-whatsapp-conversation-item]')?.dataset.conversationId;
            const top=conversationList.scrollTop;
            // Fragmento PHP propio y escapado; no ejecutar scripts ni atributos de eventos.
            const doc=new DOMParser().parseFromString(data.html,'text/html');
            if(doc.querySelector('script,iframe,object,embed')||Array.from(doc.querySelectorAll('*')).some(n=>Array.from(n.attributes).some(a=>/^on/i.test(a.name))))return;
            conversationList.replaceChildren(...Array.from(doc.body.childNodes));
            listSignature=data.html;
            applyListSearch();conversationList.scrollTop=top;
            if(focused)Array.from(conversationList.querySelectorAll('[data-whatsapp-conversation-item]')).find(n=>n.dataset.conversationId===focused)?.focus({preventScroll:true});
        }
        const total=root.querySelector('[data-whatsapp-list-count]');
        if(total)total.textContent=String(data.total)+' activas';
    }catch{}finally{clearTimeout(timeout);listBusy=false;}
}
if(conversationList){
    const scheduleList=()=>{clearInterval(listTimer);if(!document.hidden&&!listStopped){pollList();listTimer=setInterval(pollList,10000);}};
    document.addEventListener('visibilitychange',scheduleList);
    window.addEventListener('pagehide',()=>clearInterval(listTimer));
    window.addEventListener('pageshow',scheduleList);
    scheduleList();
}

